<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { formatNumber } from '../../formatters.ts';
  import type { GameRuntime } from '../types/game.js';
  import StorageFiltersBar from './StorageFiltersBar.svelte';
  import StorageSortBar from './StorageSortBar.svelte';
  import StorageGrid from './StorageGrid.svelte';
  import {
    buildStorageRoster,
    DEFAULT_STORAGE_FILTERS,
    type StorageFilterState,
  } from '../lib/storageRoster.js';
  import { GameEventType as Evt } from '../bus/events.js';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { computeStorageUltimateSlotPickTooltipScale } from '../lib/ultimateSlotPreview.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  function t(key: string, fallback: string, params?: Record<string, string | number>): string {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) return fallback;
    let got = gm.t(key, params);
    if (!got || got === key) got = fallback;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        got = got.replace(`{${k}}`, String(v));
      }
    }
    return got;
  }

  let modalFilters = $state<StorageFilterState>({ ...DEFAULT_STORAGE_FILTERS });
  let rosterTick = $state(0);
  let confirmingRemove = $state(false);

  useFacadeSubscription([Evt.STORAGE_CHANGED, Evt.TEAM_CHANGED, Evt.SHOP_CHANGED, Evt.RESOURCES_CHANGED], () => {
    rosterTick += 1;
  });

  let pickCandidates = $derived.by(() => {
    rosterTick;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    return buildStorageRoster(gm, modalFilters).creatures.filter(
      (c) => c.source === 'storage' && c.draggable,
    );
  });

  let pickShowEmptyFiltered = $derived.by(() => {
    rosterTick;
    const gm = game as GameRuntime | null;
    if (!gm) return false;
    const totalStorage = gm.storage?.length ?? 0;
    return pickCandidates.length === 0 && totalStorage > 0;
  });

  let bonus = $derived(team.ultimateSlotBonus);
  let transferPct = $derived(team.ultimateSlotTransferPercent);
  let transferPctNum = $derived(Number(transferPct) || 1);
  let isTransferMaxed = $derived(transferPctNum >= 16);
  let nextTransferPct = $derived(Math.min(16, transferPctNum + 1));

  let upgradeCost = $derived.by(() => {
    rosterTick;
    const gm = game as GameRuntime | null;
    if (!gm || typeof gm.getUpgradeCost !== 'function') return null;
    try {
      return gm.getUpgradeCost('ultimateSlotTransfer');
    } catch {
      return null;
    }
  });

  let canAffordUpgrade = $derived.by(() => {
    rosterTick;
    const gm = game as GameRuntime | null;
    if (!gm || upgradeCost === null) return false;
    const money = Number(gm.pokedollars) || 0;
    return money >= upgradeCost;
  });

  function handleUpgradeOrShop() {
    const gm = game as GameRuntime | null;
    if (!gm) return;
    if (canAffordUpgrade && typeof gm.buyUpgrade === 'function') {
      gm.buyUpgrade('ultimateSlotTransfer');
      rosterTick += 1;
    } else {
      if (typeof gm.closeUltimateSlotModal === 'function') {
        gm.closeUltimateSlotModal();
      }
      if (typeof gm.switchTab === 'function') {
        gm.switchTab('boutique');
      }
    }
  }

  function handleConfirmRemove() {
    confirmingRemove = false;
    const gm = game as GameRuntime | null;
    if (gm && typeof gm.removeFromUltimateSlot === 'function') {
      gm.removeFromUltimateSlot();
      rosterTick += 1;
    }
  }

  let pickTooltipScale = $derived.by(() => {
    rosterTick;
    transferPct;
    const gm = game as GameRuntime | null;
    if (!gm) return computeStorageUltimateSlotPickTooltipScale(null, 0.01);
    const rate = typeof gm.getUltimateSlotTransferRate === 'function'
      ? gm.getUltimateSlotTransferRate()
      : 0.01;
    return computeStorageUltimateSlotPickTooltipScale(gm, rate);
  });

  $effect(() => {
    if (!team.ultimateSlot) {
      modalFilters = { ...DEFAULT_STORAGE_FILTERS };
      confirmingRemove = false;
    }
  });
</script>

<div class="stats-content ultimate-slot-modal-content" data-action="stopPropagation" data-action-stop>
  <div class="stats-header" style="display:flex; align-items:center; justify-content:space-between; margin-bottom:12px;">
    <h2 id="ultimateSlotTitleLabel" style="display:flex; align-items:center; gap:8px; margin:0;">
      <img src="img/prestige-star.png" alt="" width="18" height="18" style="image-rendering:pixelated;" />
      {t('ultimateSlot.title', 'Slot ultime')}
    </h2>
    <button type="button" class="btn-2 x stats-close" data-action="closeUltimateSlotModal" aria-label="Fermer">✕</button>
  </div>

  <p class="ultimate-slot-desc">
    {t('ultimateSlot.description', 'Un Pokémon mentor transmet une partie de ses stats à chaque membre de l\'équipe. Il ne combat pas et ne gagne pas d\'XP.')}
  </p>

  <div class="ultimate-slot-transfer-box">
    <div class="ultimate-slot-transfer-info">
      <span class="ultimate-slot-transfer-label">{t('ultimateSlot.transferRate', 'Transfert')} :</span>
      <span class="ultimate-slot-transfer-curr">{transferPctNum}&nbsp;%</span>
      {#if !isTransferMaxed}
        <span class="ultimate-slot-transfer-arrow">→</span>
        <span class="ultimate-slot-transfer-next">{nextTransferPct}&nbsp;%</span>
      {:else}
        <span class="ultimate-slot-transfer-max">MAX</span>
      {/if}
    </div>

    {#if !isTransferMaxed && upgradeCost !== null}
      <button
        type="button"
        class="ultimate-slot-upgrade-btn {canAffordUpgrade ? 'btn-primary-bevel' : 'btn-2 is-short'}"
        onclick={handleUpgradeOrShop}
        title={canAffordUpgrade ? 'Améliorer le transfert au rang suivant' : 'Fonds insuffisants · Aller à la boutique'}
      >
        {#if canAffordUpgrade}
          Améliorer · {formatNumber(upgradeCost)}&nbsp;₽
        {:else}
          Boutique · {formatNumber(upgradeCost)}&nbsp;₽
        {/if}
      </button>
    {/if}
  </div>

  {#if team.ultimateSlot}
    <div class="ultimate-slot-mentor-row">
      <div class="ultimate-slot-mentor-left">
        <div class="ultimate-slot-mentor-visual">
          <img
            src={team.ultimateSlot.spriteUrl}
            alt=""
            class="ultimate-slot-mentor-sprite"
            width="88"
            height="88"
          />
          <div class="ultimate-slot-mentor-name">{team.ultimateSlot.displayName}</div>
          <div class="ultimate-slot-mentor-lvl">Niv. {team.ultimateSlot.level}</div>
        </div>

        {#if confirmingRemove}
          <div class="ultimate-slot-remove-confirm-box">
            <span class="ultimate-slot-remove-warn">Coupera le bonus d'équipe !</span>
            <div style="display:flex; gap:6px; width:100%;">
              <button
                type="button"
                class="btn-2 ultimate-slot-confirm-yes"
                onclick={handleConfirmRemove}
              >
                Confirmer
              </button>
              <button
                type="button"
                class="btn-2"
                style="flex:1; padding:4px;"
                onclick={() => confirmingRemove = false}
              >
                Annuler
              </button>
            </div>
          </div>
        {:else}
          <button
            type="button"
            class="btn-2 ultimate-slot-remove-btn"
            onclick={() => confirmingRemove = true}
          >
            {t('ultimateSlot.remove', 'Retirer vers le stockage')}
          </button>
        {/if}
      </div>

      <div class="ultimate-slot-bonus-panel">
        <h3 class="ultimate-slot-bonus-heading">{t('ultimateSlot.bonusPerMember', 'Bonus par membre d\'équipe')}</h3>
        <div class="statgrid-hud ultimate-slot-statgrid">
          <div class="stat-cell-hud hp">
            <span class="stat-cell-hud__label">HP</span>
            <span class="stat-cell-hud__val">+{formatNumber(bonus.hp)}</span>
          </div>
          <div class="stat-cell-hud atk">
            <span class="stat-cell-hud__label">ATK</span>
            <span class="stat-cell-hud__val">+{formatNumber(bonus.attack)}</span>
          </div>
          <div class="stat-cell-hud spatk">
            <span class="stat-cell-hud__label">ATK SP</span>
            <span class="stat-cell-hud__val">+{formatNumber(bonus.spattack)}</span>
          </div>
          <div class="stat-cell-hud def">
            <span class="stat-cell-hud__label">DEF</span>
            <span class="stat-cell-hud__val">+{formatNumber(bonus.defense)}</span>
          </div>
          <div class="stat-cell-hud spdef">
            <span class="stat-cell-hud__label">DEF SP</span>
            <span class="stat-cell-hud__val">+{formatNumber(bonus.spdefense)}</span>
          </div>
          <div class="stat-cell-hud spd">
            <span class="stat-cell-hud__label">SPD</span>
            <span class="stat-cell-hud__val">+{formatNumber(bonus.speed)}</span>
          </div>
        </div>
      </div>
    </div>
  {:else}
    <div class="storage-header-row ultimate-slot-pick-section">
      <h3 class="ultimate-slot-pick-title">{t('ultimateSlot.select', 'Choisir depuis le stockage')}</h3>

      <div class="storage-controls">
        <StorageFiltersBar idPrefix="ultimate-" bind:filters={modalFilters} onFilterChange={() => { rosterTick += 1; }} />
        <StorageSortBar idPrefix="ultimate-" sortStack={team.storageSortStack} />
      </div>

      {#if pickCandidates.length === 0 && !pickShowEmptyFiltered}
        <p class="ultimate-slot-empty">{t('ultimateSlot.emptyStorage', 'Aucun Pokémon disponible dans le stockage.')}</p>
      {:else}
        <div class="storage-container">
          <div class="ultimate-slot-pick-scroll">
            <StorageGrid
              listId="ultimateSlotPickList"
              pickMode="ultimateSlot"
              forceSpriteOnly={true}
              creatures={pickCandidates}
              showEmptyFiltered={pickShowEmptyFiltered}
              scrollRootSelector=".ultimate-slot-pick-scroll"
              ultimateSlotBonusMaxima={pickTooltipScale.maxima}
              ultimateSlotBonusTotalMax={pickTooltipScale.totalMax}
            />
          </div>
        </div>
      {/if}
    </div>
  {/if}
</div>

